        if self.byte_start > 9_007_199_254_740_991 { return Err("integer_interop_budget".into()); }

        if self.event_at.as_ref().is_some_and(|x| x.trim().is_empty()) { return Err("empty_SourceAnchor_event_at".into()); }

        if self.message_id.as_ref().is_some_and(|x| x.trim().is_empty()) { return Err("empty_SourceAnchor_message_id".into()); }

